pageCss:
.av2-demo{display:flex;flex-wrap:wrap;gap:14px;margin:10px 0}
.av2-demo figure{margin:0;text-align:center;font-size:8.4pt}
.av2-demo img{display:block;width:128px;height:128px;border:1px solid #99a8bd;background:repeating-conic-gradient(#e8eef7 0 25%,#fff 0 50%) 0 0/16px 16px}
.av2-verdict{font-size:8.8pt;padding:6px 10px;border:1px solid #99a8bd;background:#f3f6fa}
.av2-verdict b{font-family:var(--font-mono)}
.dd-box{border:1px solid #99a8bd;background:#f3f6fa;box-shadow:inset 1px 1px 0 #fff;margin:10px 0;padding:6px 0}
.dd-row{display:grid;gap:10px;align-items:center;padding:3px 10px;font-size:8.6pt;border-bottom:1px solid #e4eaf3}
.dd-row:last-child{border-bottom:0}
.dd-row.head{font-weight:700;background:#e8eef7}
.dd-speeds .dd-row{grid-template-columns:2.2fr 1fr 1fr 1fr 1fr}
.dd-lossless .dd-row{grid-template-columns:2fr 1fr 1fr}
.dd-num{font-family:var(--font-mono);font-size:8.2pt;color:#3a4a5e}
.av2-fig{margin:14px 0}
.av2-stack{display:flex;flex-wrap:wrap;gap:8px}
.av2-stack img{width:400px;max-width:100%;height:auto;image-rendering:pixelated;border:1px solid #99a8bd}
.av2-fig.flip .av2-stack{display:block;cursor:pointer;width:400px;max-width:100%}
.av2-fig.flip .av2-stack img{display:none}
.av2-fig.flip .av2-stack img.on{display:block}
.av2-tag{font-family:var(--font-mono);font-size:8.4pt;margin:4px 0}
.av2-fig figcaption{font-size:8.4pt;margin-top:4px}
.av2-note{font-size:8.4pt;color:#3a4a5e}
.av2-code{font-family:var(--font-mono);font-size:8.4pt;background:#f3f6fa;border:1px solid #99a8bd;padding:6px 10px;overflow-x:auto}
@media(max-width:620px){.dd-speeds .dd-row,.dd-lossless .dd-row{grid-template-columns:1fr 1fr}}

