(function(){
  // The demo: report whether each image decoded. img.decode() rejects on a file
  // the browser fetched and could not read, which is the case this page is about.
  var out = document.getElementById("av2-verdict");
  var a = document.getElementById("av2-a"), b = document.getElementById("av2-b"), c = document.getElementById("av2-c");
  if (out && a && b && c && a.decode) {
    var ok = function(img){ return img.decode().then(function(){ return img.naturalWidth > 0; }, function(){ return false; }); };
    Promise.all([ok(a), ok(b), ok(c)]).then(function(r){
      var picked = c.currentSrc && c.currentSrc.indexOf("demo-av2") >= 0 ? "the AV2 source" : "the WebP fallback";
      var s = "AV1: <b>" + (r[0] ? "drew" : "broken") + "</b>. AV2: <b>" + (r[1] ? "drew" : "broken") + "</b>. With a fallback, your browser chose " + picked + ", which <b>" + (r[2] ? "drew" : "broke") + "</b>.";
      if (r[1]) s += " Your browser decodes AV2, which none did when this was written.";
      else if (!r[2] && picked === "the AV2 source") s += " That's the trap: the type matched, the decode failed, and the fallback never loaded.";
      else if (!r[0]) s += " This browser doesn't decode AVIF at all, so the fallback did its job.";
      out.innerHTML = s;
    });
  }
  // The figures: flip between the three images in place, one click at a time.
  var figs = document.querySelectorAll(".av2-fig");
  for (var i = 0; i < figs.length; i++) (function(fig){
    var imgs = fig.querySelectorAll(".av2-stack img"), k = 0;
    if (imgs.length !== 3) return;
    var tag = document.createElement("p"); tag.className = "av2-tag";
    var show = function(){ for (var j = 0; j < 3; j++) imgs[j].className = j === k ? "on" : ""; tag.textContent = imgs[k].getAttribute("data-label") + " (" + (k + 1) + " of 3, click to flip)"; };
    fig.classList.add("flip"); fig.insertBefore(tag, fig.firstChild); show();
    fig.querySelector(".av2-stack").addEventListener("click", function(){ k = (k + 1) % 3; show(); });
    // A lazy image that is display:none is never near the viewport, so the two
    // hidden frames would never fetch and the first flip would show a blank.
    // Promote all three to eager once the figure itself comes close.
    var eager = function(){ for (var j = 0; j < 3; j++) imgs[j].loading = "eager"; };
    if ("IntersectionObserver" in window) {
      var io = new IntersectionObserver(function(es){ if (es[0].isIntersecting) { eager(); io.disconnect(); } }, { rootMargin: "400px" });
      io.observe(fig);
    } else eager();
  })(figs[i]);
})();
